import{_t as e,it as t,n,rt as r}from"./chunks/framework.D72WcpWg.js";var i=JSON.parse(`{"title":"Known Limitations","description":"Behaviors and gaps worth knowing before building on Nuxt UI FormKit - silent no-ops, validation timing, and what isn't supported.","frontmatter":{"title":"Known Limitations","description":"Behaviors and gaps worth knowing before building on Nuxt UI FormKit - silent no-ops, validation timing, and what isn't supported."},"headers":[],"relativePath":"getting-started/known-limitations.md","filePath":"getting-started/known-limitations.md","lastUpdated":1792167002000}`),a={name:`getting-started/known-limitations.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to “Known Limitations”">​</a></h1><p>Most of these fail <strong>silently</strong> - no error, no warning, just a missing label or a validation message that never appears - so they&#39;re worth reading once.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to “Setup”">​</a></h2><ul><li><strong>Inputs are not auto-registered.</strong> The module only adds a plugin, the composables, and <code>FUDataView</code>/<code>FUDataEdit</code>/<code>FUDataDebug</code>/<code>FUAutoForm</code>. The <code>nuxtUI*</code> input and output types exist only once your <code>formkit.config.ts</code> registers them via <a href="/nuxt-ui-formkit/getting-started/installation#formkit-configuration"><code>createNuxtUiFormkitConfig()</code></a>, and that file is only picked up if <code>@formkit/nuxt</code> is in your <code>modules</code>.</li><li><strong>Multi-step needs its plugin.</strong> <code>nuxtUIMultiStep</code>/<code>nuxtUIStep</code> do nothing unless you call <code>createNuxtUiFormkitConfig({ multiStep: true })</code> (or register <code>createMultiStepPlugin()</code> yourself). In development a <code>nuxtUIMultiStep</code> without the plugin logs a console warning saying so. See <a href="/nuxt-ui-formkit/components/multi-step">Multi-Step</a>.</li><li><strong>Don&#39;t override <code>plugins</code> after spreading the helper.</strong> <code>defaultConfig({ ...createNuxtUiFormkitConfig(), plugins: [x] })</code> replaces the whole array and silently drops the asterisk plugin (required fields lose their <code>*</code>). Pass yours as <code>createNuxtUiFormkitConfig({ plugins: [x] })</code>, which appends them.</li><li><strong>Schemas can only use globally registered Nuxt UI components.</strong> The module registers <code>UButton</code>, <code>UIcon</code>, <code>UTabs</code>, <code>UUser</code> and <code>UTooltip</code>. Any other <code>$cmp: &#39;UXxx&#39;</code> in a schema renders as an unstyled custom element.</li><li><strong>SSR is untested.</strong> The playground runs with <code>ssr: false</code>; nothing here has been verified for server rendering or hydration.</li></ul><h2 id="validation-timing" tabindex="-1">Validation timing <a class="header-anchor" href="#validation-timing" aria-label="Permalink to “Validation timing”">​</a></h2><p>FormKit reveals validation messages on <code>blur</code> by default, and Nuxt UI components don&#39;t all emit one.</p><ul><li><strong><code>nuxtUIColorPicker</code> is pointer-only.</strong> Nothing inside <code>UColorPicker</code> is focusable, so &quot;blur&quot; means releasing the pointer after picking a color; keyboard users can&#39;t operate it at all.</li><li><strong><code>nuxtUISelect</code> reveals on dropdown close only.</strong> Tabbing through without opening it shows nothing. Use <code>&#39;live&#39;</code>, or <code>nuxtUISelectMenu</code>, which has no such gap. See <a href="/nuxt-ui-formkit/components/inputs#nuxtuiselect">Selection Components</a>.</li><li><strong><code>required</code> passes for a boolean <code>false</code>.</strong> On <code>nuxtUICheckbox</code>/<code>nuxtUISwitch</code>, use the <code>accepted</code> rule instead.</li></ul><h2 id="forms-and-composables" tabindex="-1">Forms and composables <a class="header-anchor" href="#forms-and-composables" aria-label="Permalink to “Forms and composables”">​</a></h2><ul><li><strong><code>useFormKitForm(id)</code> is keyed on the form&#39;s <code>id</code>, not its <code>name</code></strong>, and the form must be mounted in the DOM. <code>submit()</code> can&#39;t report when FormKit&#39;s own submission finishes; <code>isLoading</code> only wraps the <code>handler</code> you pass.</li><li><strong><code>hasErrors</code> is not <code>!isValid</code>.</strong> <code>hasErrors</code> counts only error <em>messages</em> (e.g. from <code>setErrors</code>); a form with failed validation rules reports <code>hasErrors: false</code>. Use <code>isValid</code> for rule failures.</li><li><strong><code>isDirty</code> is sticky by default</strong> - it stays <code>true</code> after a field is edited back to its original value. Set <code>dirty-behavior=&quot;compare&quot;</code> (<code>FUDataEdit</code> has a <code>dirtyBehavior</code> prop) to track the live difference.</li><li><strong>Overlays aren&#39;t concurrent.</strong> <code>useFormKitOverlay().edit()</code>/<code>auto()</code> share one overlay instance; a second call before the first resolves takes it over. See <a href="/nuxt-ui-formkit/components/overlay">One Overlay Instance at a Time</a>.</li><li><strong>Autosave attaches at form creation only.</strong> It needs a stable form <code>name</code>, covers the root form (not nested groups), and can&#39;t be added later from <code>useFormKitForm</code>. See <a href="/nuxt-ui-formkit/api/utilities#createautosaveplugin"><code>createAutosavePlugin</code></a>.</li></ul><h2 id="repeaters-and-schemas" tabindex="-1">Repeaters and schemas <a class="header-anchor" href="#repeaters-and-schemas" aria-label="Permalink to “Repeaters and schemas”">​</a></h2><ul><li><strong><code>node.at(&#39;items.0.email&#39;)</code> can&#39;t reach into <code>nuxtUIRepeater</code>.</strong> The repeater&#39;s outer and inner nodes share a name, so FormKit&#39;s address lookup fails silently. The Standard Schema bridge works around this; your own code addressing repeater rows has to as well.</li><li><strong>Inside repeater rows, read sibling values with <code>$node.value.&lt;field&gt;</code>.</strong> <code>$get(name)</code> resolves by <code>id</code>, not by <code>name</code>.</li><li><strong>The schema expression language has no unary <code>!</code>.</strong> <code>if: &#39;!$value&#39;</code> is silently ignored; compare explicitly instead.</li></ul><h2 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to “Inputs”">​</a></h2><ul><li><strong>Date inputs emit <code>@internationalized/date</code> objects by default</strong> (<code>CalendarDate</code> etc.), which aren&#39;t JSON-serializable. Set <code>valueType: &#39;date&#39;</code> or <code>&#39;iso&#39;</code> for plain values - see <a href="/nuxt-ui-formkit/components/inputs#nuxtuiinputdate"><code>nuxtUIInputDate</code></a>.</li><li><strong><code>color</code> is overridden while a field is invalid</strong> - the wrapped component is switched to its <code>error</code> color.</li><li><strong>FormKit&#39;s own label/help/messages chrome always surrounds the Nuxt UI component</strong>, so you won&#39;t get Nuxt UI&#39;s <code>UFormField</code> layout.</li><li><strong><code>@formkit/addons</code> plugins that assume native FormKit types silently no-op.</strong> <code>createMaxLengthCountdownPlugin</code> and <code>createFloatingLabelsPlugin</code> don&#39;t work with <code>nuxtUI*</code> types.</li></ul><h2 id="fuautoform" tabindex="-1">FUAutoForm <a class="header-anchor" href="#fuautoform" aria-label="Permalink to “FUAutoForm”">​</a></h2><ul><li><strong>Fields it can&#39;t map are dropped, not errored.</strong> <code>null</code>, <code>undefined</code>, functions and other non-plain values never become inputs; with Zod, only string, number, boolean, date, array and object schemas map - enums, unions and literals are skipped.</li><li><strong>Schema introspection is by duck-typing</strong>, tested against Valibot 1.x and Zod 4. Zod 3 isn&#39;t supported, and other Standard Schema libraries (e.g. ArkType) get no inference - they work for <a href="/nuxt-ui-formkit/components/standard-schema">validation</a>, not for building the form.</li></ul><h2 id="localization" tabindex="-1">Localization <a class="header-anchor" href="#localization" aria-label="Permalink to “Localization”">​</a></h2><p>Built-in labels are English-only unless noted: &quot;Save&quot;/&quot;Cancel&quot;/&quot;Reset&quot; on <code>FUDataEdit</code> and the overlays, &quot;Keep editing&quot;/&quot;Discard&quot; in the <code>confirmDiscard</code> prompt, &quot;Yes&quot;/&quot;No&quot; on <code>FUOutputBoolean</code>, and &quot;Add Item&quot; on the repeater. Multi-step&#39;s Previous/Next resolve through FormKit&#39;s <code>$ui.prev</code>/<code>$ui.next</code> i18n keys. Most of these can be overridden through props.</p><h2 id="not-implemented" tabindex="-1">Not implemented <a class="header-anchor" href="#not-implemented" aria-label="Permalink to “Not implemented”">​</a></h2><p><code>UStepper</code> as a multi-step display mode (tabs only), <code>FUOutputAvatar</code>, and <code>FUOutputProgressGroup</code>.</p>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};